declare total numeric; amendment_total numeric; begin
-- E14_TENANT_GUARD_BEGIN
  if coalesce(current_setting('role',true),'') <> 'service_role' and (
    auth.uid() is null or not exists(
      select 1 from public.execution_service_contracts scope_contract
      where scope_contract.id=p_contract_id
        and public.is_company_member(scope_contract.company_id)
        and (public.has_company_permission(scope_contract.company_id,'execution.contracts.view')
          or public.has_company_permission(scope_contract.company_id,'execution.contracts.manage')
          or public.has_company_permission(scope_contract.company_id,'execution.contracts.approve')
          or public.has_company_permission(scope_contract.company_id,'execution.contracts.amend'))
    )) then
    raise exception using errcode='42501',message='Contrato indisponível ou sem autorização.';
  end if;
-- E14_TENANT_GUARD_END

  select coalesce(sum(total_value),0) into total from public.execution_service_contract_items where contract_id=p_contract_id;
  select coalesce(sum(value_change),0) into amendment_total from public.execution_service_contract_amendments where contract_id=p_contract_id;
  update public.execution_service_contracts set original_value=total,amendments_value=amendment_total,current_value=greatest(0,total+amendment_total),updated_at=now() where id=p_contract_id;
  return greatest(0,total+amendment_total);
end;

